import contactPageData from '../pages/contactPageData';

const dayMap = {
  Pirmdiena: 'Monday',
  Otrdiena: 'Tuesday',
  Trešdiena: 'Wednesday',
  Ceturtdiena: 'Thursday',
  Piektdiena: 'Friday',
  Sestdiena: 'Saturday',
  Svētdiena: 'Sunday',
};

const parseHours = (time) => {
  if (!time || time.toLowerCase() === 'slēgts') return null;
  const [opens, closes] = time.split(' - ').map((part) => part.trim());
  if (!opens || !closes) return null;
  return { opens, closes };
};

const buildLocalBusinessJsonLd = () => {
  const data = contactPageData[0];
  const { phoneNumber, countryCode, eMail } = data.contacts;

  const openingHoursSpecification = data.workingHours
    .map((row) => {
      const hours = parseHours(row.time);
      if (!hours) return null;
      return {
        '@type': 'OpeningHoursSpecification',
        dayOfWeek: dayMap[row.day],
        opens: hours.opens,
        closes: hours.closes,
      };
    })
    .filter(Boolean);

  return {
    '@context': 'https://schema.org',
    '@type': 'Store',
    name: 'Tropiks AZ',
    legalName: 'SIA TROPIKS AZ',
    url: 'https://tropiks.lv/',
    image: 'https://tropiks.lv/og-image.png',
    telephone: `${countryCode}${phoneNumber}`,
    email: eMail,
    address: {
      '@type': 'PostalAddress',
      streetAddress: 'Krasta iela 91/93',
      addressLocality: 'Rīga',
      postalCode: 'LV-1019',
      addressCountry: 'LV',
    },
    geo: {
      '@type': 'GeoCoordinates',
      latitude: 56.9300169,
      longitude: 24.1504899,
    },
    openingHoursSpecification,
    priceRange: '€€',
    description:
      'Tropiks AZ — pirotehnikas veikals Rīgā. Katalogs, drošības ieteikumi un kontakti.',
  };
};

export default buildLocalBusinessJsonLd;
