import { useState } from 'react';
import contactPageData from '../data/pages/contactPageData';
import buildLocalBusinessJsonLd from '../data/seo/localBusinessJsonLd';
import storeMap from '../assets/maps/store-location.svg';
import usePageMeta from '../functions/usePageMeta';
import useToTop from '../functions/useToTop';

const localBusinessJsonLd = buildLocalBusinessJsonLd();

const ContactPage = () => {
  useToTop();
  usePageMeta({
    title: 'Kontakti',
    description:
      'Tropiks AZ kontakttālrunis, e-pasts, adrese Krasta ielā 91/93, Rīgā, un veikala darba laiks.',
    path: '/kontakti',
    jsonLdId: 'local-business-jsonld',
    jsonLd: localBusinessJsonLd,
  });

  const data = contactPageData[0];
  const [form, setForm] = useState({ name: '', email: '', message: '' });
  const [formError, setFormError] = useState('');

  const onChange = (event) => {
    setForm((prev) => ({ ...prev, [event.target.name]: event.target.value }));
  };

  const onSubmit = (event) => {
    event.preventDefault();
    if (!form.name.trim() || !form.email.trim() || !form.message.trim()) {
      setFormError('Lūdzu aizpildiet visus laukus.');
      return;
    }
    setFormError('');
    const subject = encodeURIComponent(`Ziņa no mājaslapas — ${form.name.trim()}`);
    const body = encodeURIComponent(
      `Vārds: ${form.name.trim()}\nE-pasts: ${form.email.trim()}\n\n${form.message.trim()}`
    );
    window.location.href = `mailto:${data.contacts.eMail}?subject=${subject}&body=${body}`;
  };

  return (
    <main className="contact-page">
      <section className="main-page-title">
        <h1>
          Mūsu <span>KONTAKTI</span>
        </h1>
        <p className="page-lead">
          Apmeklējiet veikalu Rīgā, zvaniet, rakstiet e-pastu vai nosūtiet ziņu — bez trešo pušu
          sīkdatnēm.
        </p>
      </section>

      <section className="contact-top-grid">
        <a
          className="static-map-link"
          href={data.contacts.googleMapsLink}
          target="_blank"
          rel="noopener noreferrer"
        >
          <img
            src={storeMap}
            alt={`Veikala atrašanās vieta: ${data.contacts.adress}`}
            className="static-map"
            width="800"
            height="450"
            loading="lazy"
            decoding="async"
          />
          <span className="static-map-caption">
            Atvērt atrašanās vietu Google Maps (ārēja saite)
          </span>
        </a>

        <address className="contact-address">
          <div className="contact-card">
            <strong>Veikala adrese</strong>
            <a href={data.contacts.googleMapsLink} target="_blank" rel="noopener noreferrer">
              {data.contacts.adress}
            </a>
          </div>
          <div className="contact-card">
            <strong>Kontakttālrunis</strong>
            <a href={`tel:${data.contacts.countryCode}${data.contacts.phoneNumber}`}>
              {data.contacts.countryCode} {data.contacts.phoneNumber}
            </a>
          </div>
          <div className="contact-card">
            <strong>E-pasts</strong>
            <a href={`mailto:${data.contacts.eMail}`}>{data.contacts.eMail}</a>
          </div>
        </address>
      </section>

      <section className="contact-hours-section">
        <h2>Veikala darba laiks</h2>
        <div className="contact-hours-grid">
          <section className="contact-table-container">
            <table>
              <caption>Svētku dienās</caption>
              <thead>
                <tr>
                  <th scope="col">Diena</th>
                  <th scope="col">Laiks</th>
                </tr>
              </thead>
              <tbody>
                {data.holidayworkingHours.map((e) => (
                  <tr key={e.day}>
                    <td>{e.day}</td>
                    <td>{e.time}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </section>

          <section className="contact-table-container">
            <table>
              <caption>Ikdienā</caption>
              <thead>
                <tr>
                  <th scope="col">Diena</th>
                  <th scope="col">Laiks</th>
                </tr>
              </thead>
              <tbody>
                {data.workingHours.map((e) => (
                  <tr key={e.day}>
                    <td>{e.day}</td>
                    <td>{e.time}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </section>
        </div>
      </section>

      <section className="contact-form-section">
        <h2>Nosūtīt ziņu</h2>
        <p>
          Forma atver Jūsu e-pasta programmu — ziņa netiek sūtīta caur ārējiem serveriem.
        </p>
        <form className="contact-form" onSubmit={onSubmit} noValidate>
          <label htmlFor="contactName">
            Vārds
            <input
              id="contactName"
              name="name"
              type="text"
              autoComplete="name"
              value={form.name}
              onChange={onChange}
              required
            />
          </label>
          <label htmlFor="contactEmail">
            E-pasts
            <input
              id="contactEmail"
              name="email"
              type="email"
              autoComplete="email"
              value={form.email}
              onChange={onChange}
              required
            />
          </label>
          <label htmlFor="contactMessage">
            Ziņa
            <textarea
              id="contactMessage"
              name="message"
              rows="5"
              value={form.message}
              onChange={onChange}
              required
            />
          </label>
          {formError && <p className="form-error">{formError}</p>}
          <button type="submit" className="button-link">
            Sagatavot e-pastu
          </button>
        </form>
      </section>

      <section className="contact-about">
        <h2>Par mums</h2>
        <p>{data.intro}</p>
        <p>{data.mission}</p>
        <p>{data.principleIntro}</p>
        <ul className="principle-grid">
          {data.principles.map((e) => (
            <li key={e.principle} className="principle-card">
              <strong>{e.principle}</strong>
              <span>{e.value}</span>
            </li>
          ))}
        </ul>
      </section>
      
      <section className="contact-props">
        <h2>{data.propsIntro}</h2>
        <section className="contact-table-container">
          <table>
            <thead>
              <tr>
                <th scope="col">REKVIZĪTS</th>
                <th scope="col">DATI</th>
              </tr>
            </thead>
            <tbody>
              {data.props.map((e) => (
                <tr key={e.name}>
                  <td>{e.name}</td>
                  <td>{e.value}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </section>
      </section>
    </main>
  );
};

export default ContactPage;
